import axios from '@/utils/axiosConfig';
import { useConfirm } from 'primevue/useconfirm';
export default {
  name: 'SalesActivity',
  setup() {
    return {
      $confirm: useConfirm()
    };
  },
  data() {
    return {
      visits: [],
      customers: [],
      tasks: [],
      users: [],
      loading: false,
      saving: false,
      gettingLocation: false,
      searchQuery: '',
      filterStatus: null,
      filterType: null,
      filterDateRange: null,
      showFormDialog: false,
      showCustomerDialog: false,
      showDetailDialog: false,
      editingVisit: null,
      selectedVisit: null,
      form: this.emptyForm(),
      newCustomer: {
        company_name: '',
        industry: '',
        phone: '',
        email: '',
        address: '',
        contact_name: '',
        contact_position: ''
      },
      visitTypeOptions: [{
        label: 'On-site',
        value: 'on_site'
      }, {
        label: 'Online Meeting',
        value: 'online'
      }, {
        label: 'Phone Call',
        value: 'phone'
      }, {
        label: 'Site Survey',
        value: 'survey'
      }, {
        label: 'POC / Demo',
        value: 'demo'
      }],
      visitStatusOptions: [{
        label: 'กำหนดการ',
        value: 'scheduled'
      }, {
        label: 'เสร็จสิ้น',
        value: 'done'
      }, {
        label: 'ยกเลิก',
        value: 'cancelled'
      }, {
        label: 'Follow-up',
        value: 'follow_up'
      }],
      kpiList: [{
        key: 'scheduled',
        label: 'กำหนดการ',
        icon: 'pi pi-clock',
        colorClass: 'kpi-scheduled'
      }, {
        key: 'done',
        label: 'เสร็จสิ้น',
        icon: 'pi pi-check-circle',
        colorClass: 'kpi-done'
      }, {
        key: 'follow_up',
        label: 'Follow-up',
        icon: 'pi pi-refresh',
        colorClass: 'kpi-followup'
      }, {
        key: 'cancelled',
        label: 'ยกเลิก',
        icon: 'pi pi-times-circle',
        colorClass: 'kpi-cancelled'
      }]
    };
  },
  computed: {
    filteredVisits() {
      let result = [...this.visits];
      if (this.filterStatus) result = result.filter(v => v.status === this.filterStatus);
      if (this.filterType) result = result.filter(v => v.visit_type === this.filterType);
      if (this.filterDateRange && this.filterDateRange[0]) {
        // copy Date ใหม่ก่อน setHours กัน mutate ค่าใน v-model ของ Calendar
        const from = new Date(this.filterDateRange[0]);
        from.setHours(0, 0, 0, 0);
        const to = new Date(this.filterDateRange[1] || this.filterDateRange[0]);
        to.setHours(23, 59, 59, 999);
        result = result.filter(v => {
          const d = new Date(v.visit_date);
          return d >= from && d <= to;
        });
      }
      if (this.searchQuery) {
        const q = this.searchQuery.toLowerCase();
        result = result.filter(v => v.company_name?.toLowerCase().includes(q) || v.location?.toLowerCase().includes(q) || v.agenda?.toLowerCase().includes(q) || v.summary?.toLowerCase().includes(q) || v.task_name?.toLowerCase().includes(q));
      }
      return result;
    }
  },
  mounted() {
    this.loadAll();
  },
  methods: {
    emptyForm() {
      return {
        visit_date: null,
        visit_end_date: null,
        customer_id: null,
        task_id: null,
        visit_type: 'on_site',
        location: '',
        latitude: null,
        longitude: null,
        status: 'scheduled',
        agenda: '',
        summary: '',
        action_items: [],
        next_visit_date: null,
        internal_attendees: [],
        customer_attendees: []
      };
    },
    async loadAll() {
      this.loading = true;
      try {
        const [visitsRes, customersRes, tasksRes, usersRes] = await Promise.all([axios.get('/api/sales-visits'), axios.get('/api/sales-visits/customers'), axios.get('/api/tasks'), axios.get('/api/users')]);
        this.visits = visitsRes.data;
        this.customers = customersRes.data;
        this.tasks = tasksRes.data.map(t => ({
          ...t,
          display_name: `${t.so_number ? '[' + t.so_number + '] ' : ''}${t.task_name}`
        }));
        this.users = usersRes.data.map(u => ({
          id: u.id,
          name: `${u.firstname} ${u.lastname}${u.nickname ? ` (${u.nickname})` : ''}`,
          position: u.position
        }));
      } catch (e) {
        console.error(e);
      } finally {
        this.loading = false;
      }
    },
    countByStatus(status) {
      return this.visits.filter(v => v.status === status).length;
    },
    openCreateDialog() {
      this.editingVisit = null;
      this.form = this.emptyForm();
      this.showFormDialog = true;
    },
    openEditDialog(visit) {
      this.editingVisit = visit;
      this.form = {
        ...visit,
        visit_date: visit.visit_date ? new Date(visit.visit_date) : null,
        visit_end_date: visit.visit_end_date ? new Date(visit.visit_end_date) : null,
        next_visit_date: visit.next_visit_date ? new Date(visit.next_visit_date) : null,
        internal_attendees: visit.internal_attendees || [],
        customer_attendees: (visit.customer_attendees || []).map(a => ({
          name: a.name || '',
          position: a.position || '',
          email: a.email || '',
          phone: a.phone || ''
        })),
        // รองรับข้อมูลเก่าที่ action_items เป็น string แทน object
        action_items: (visit.action_items || []).map(a => typeof a === 'object' ? {
          text: a.text || '',
          done: !!a.done
        } : {
          text: String(a),
          done: false
        })
      };
      this.showFormDialog = true;
    },
    openDetailDialog(visit) {
      this.selectedVisit = visit;
      this.showDetailDialog = true;
    },
    async saveVisit() {
      if (!this.form.visit_date) return;
      // ตรวจเวลาสิ้นสุดต้องไม่ก่อนเวลาเริ่ม
      if (this.form.visit_end_date && new Date(this.form.visit_end_date) < new Date(this.form.visit_date)) {
        this.$toast.add({
          severity: 'warn',
          summary: 'เวลาไม่ถูกต้อง',
          detail: 'เวลาสิ้นสุดต้องหลังจากเวลาเริ่มต้น',
          life: 3000
        });
        return;
      }
      this.saving = true;
      try {
        const payload = {
          ...this.form,
          visit_date: this.form.visit_date instanceof Date ? this.fmtDate(this.form.visit_date) : this.form.visit_date,
          visit_end_date: this.form.visit_end_date instanceof Date ? this.fmtDate(this.form.visit_end_date) : this.form.visit_end_date,
          next_visit_date: this.form.next_visit_date instanceof Date ? this.fmtDate(this.form.next_visit_date) : this.form.next_visit_date,
          internal_attendees: (this.form.internal_attendees || []).map(u => typeof u === 'object' ? {
            id: u.id,
            name: u.name,
            position: u.position
          } : u),
          // ตัด action item ที่ไม่ได้กรอกข้อความออกก่อนบันทึก
          action_items: (this.form.action_items || []).filter(a => a && a.text && String(a.text).trim()).map(a => ({
            text: String(a.text).trim(),
            done: !!a.done
          }))
        };
        if (this.editingVisit) {
          await axios.put(`/api/sales-visits/${this.editingVisit.id}`, payload);
          this.$toast.add({
            severity: 'success',
            summary: 'บันทึกแล้ว',
            life: 2000
          });
        } else {
          await axios.post('/api/sales-visits', payload);
          this.$toast.add({
            severity: 'success',
            summary: 'สร้าง Visit แล้ว',
            life: 2000
          });
        }
        this.showFormDialog = false;
        await this.loadAll();
      } catch (e) {
        this.$toast.add({
          severity: 'error',
          summary: 'ผิดพลาด',
          detail: e.response?.data?.error || 'ไม่สามารถบันทึกได้',
          life: 3000
        });
      } finally {
        this.saving = false;
      }
    },
    async createCustomer() {
      try {
        const res = await axios.post('/api/sales-visits/customers', this.newCustomer);
        this.customers.push(res.data);
        this.form.customer_id = res.data.id;
        this.showCustomerDialog = false;
        this.newCustomer = {
          company_name: '',
          industry: '',
          phone: '',
          email: '',
          address: '',
          contact_name: '',
          contact_position: ''
        };
        this.$toast.add({
          severity: 'success',
          summary: 'สร้างลูกค้าแล้ว',
          life: 2000
        });
      } catch (e) {
        this.$toast.add({
          severity: 'error',
          summary: 'ผิดพลาด',
          life: 3000
        });
      }
    },
    deleteVisit(visit) {
      this.$confirm.require({
        message: `ลบการเข้าพบ "${visit.company_name || 'ไม่ระบุลูกค้า'}" วันที่ ${this.formatDate(visit.visit_date)}?`,
        header: 'ยืนยันการลบ',
        icon: 'pi pi-exclamation-triangle',
        acceptLabel: 'ลบ',
        rejectLabel: 'ยกเลิก',
        acceptClass: 'p-button-danger',
        accept: async () => {
          try {
            await axios.delete(`/api/sales-visits/${visit.id}`);
            await this.loadAll();
            this.$toast.add({
              severity: 'success',
              summary: 'ลบแล้ว',
              life: 2000
            });
          } catch (e) {
            this.$toast.add({
              severity: 'error',
              summary: 'ลบไม่สำเร็จ',
              detail: e.response?.data?.error || 'ไม่สามารถลบได้',
              life: 3000
            });
          }
        }
      });
    },
    getLocation() {
      if (!navigator.geolocation) {
        this.$toast.add({
          severity: 'warn',
          summary: 'ไม่รองรับ',
          detail: 'เบราว์เซอร์นี้ไม่รองรับการระบุตำแหน่ง',
          life: 3000
        });
        return;
      }
      this.gettingLocation = true;
      navigator.geolocation.getCurrentPosition(pos => {
        this.form.latitude = pos.coords.latitude;
        this.form.longitude = pos.coords.longitude;
        this.gettingLocation = false;
        if (!this.form.location) this.form.location = `${pos.coords.latitude.toFixed(6)}, ${pos.coords.longitude.toFixed(6)}`;
      }, err => {
        this.gettingLocation = false;
        const detail = err.code === err.PERMISSION_DENIED ? 'ไม่ได้รับอนุญาตให้เข้าถึงตำแหน่ง' : 'ไม่สามารถระบุตำแหน่งได้';
        this.$toast.add({
          severity: 'warn',
          summary: 'ระบุตำแหน่งไม่สำเร็จ',
          detail,
          life: 3000
        });
      }, {
        enableHighAccuracy: true,
        timeout: 10000
      });
    },
    getVisitTypeLabel(t) {
      const map = {
        on_site: 'On-site',
        online: 'Online Meeting',
        phone: 'Phone Call',
        survey: 'Site Survey',
        demo: 'POC/Demo'
      };
      return map[t] || t;
    },
    // ชื่อทีมที่ไปเข้าพบ (แสดงสูงสุด 3 คน เกินนั้น +N)
    getTeamNames(visit) {
      const list = visit.internal_attendees || [];
      if (!list.length) return '';
      const names = list.map(u => u.name || u);
      return names.length <= 3 ? names.join(', ') : names.slice(0, 3).join(', ') + ` +${names.length - 3}`;
    },
    // กำหนดการที่เลยเวลามาแล้วแต่ยังไม่เสร็จ/ไม่ถูกยกเลิก
    isVisitOverdue(visit) {
      if (!visit.visit_date || visit.status === 'done' || visit.status === 'cancelled') return false;
      return new Date(visit.visit_date) < new Date();
    },
    getVisitTypeIcon(t) {
      const map = {
        on_site: 'pi pi-map-marker',
        online: 'pi pi-video',
        phone: 'pi pi-phone',
        survey: 'pi pi-compass',
        demo: 'pi pi-desktop'
      };
      return map[t] || 'pi pi-calendar';
    },
    getStatusLabel(s) {
      const map = {
        scheduled: 'กำหนดการ',
        done: 'เสร็จสิ้น',
        cancelled: 'ยกเลิก',
        follow_up: 'Follow-up'
      };
      return map[s] || s;
    },
    formatVisitDate(d) {
      if (!d) return '';
      return new Date(d).toLocaleString('th-TH', {
        day: 'numeric',
        month: 'short',
        year: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      });
    },
    formatVisitTime(d) {
      if (!d) return '';
      return new Date(d).toLocaleTimeString('th-TH', {
        hour: '2-digit',
        minute: '2-digit'
      });
    },
    formatDate(d) {
      if (!d) return '';
      return new Date(d).toLocaleDateString('th-TH', {
        day: 'numeric',
        month: 'short',
        year: '2-digit'
      });
    },
    fmtDate(d) {
      if (!d) return null;
      const x = new Date(d);
      return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, '0')}-${String(x.getDate()).padStart(2, '0')}`;
    }
  }
};
